            JavaScript

    // Determinant using Gaussian elimination
function determinant(mat, n) {
    let det = 1.0;

    for (let i = 0; i < n; i++) {

        // Find pivot
        let pivot = i;
        for (let j = i + 1; j < n; j++) {
            if (Math.abs(mat[j][i]) > Math.abs(mat[pivot][i]))
                pivot = j;
        }

        // If pivot is zero → determinant = 0
        if (Math.abs(mat[pivot][i]) < 1e-9)
            return 0;

        // Swap rows
        if (i !== pivot) {
            [mat[i], mat[pivot]] = [mat[pivot], mat[i]];
            det *= -1;
        }

        det *= mat[i][i];

        // Eliminate below
        for (let j = i + 1; j < n; j++) {
            let factor = mat[j][i] / mat[i][i];
            for (let k = i; k < n; k++) {
                mat[j][k] -= factor * mat[i][k];
            }
        }
    }

    return det;
}

// Function to compute number of spanning trees 
// using adjacency matrix
function numOfSpanningTree(graph, v) {

    // Laplacian matrix
    let L = Array.from({ length: v }, () => Array(v).fill(0));

    for (let i = 0; i < v; i++) {
        let degree = 0;

        for (let j = 0; j < v; j++) {
            if (graph[i][j] === 1) {
                degree++;
                if (i !== j) L[i][j] = -1;
            }
        }

        L[i][i] = degree;
    }

    // Minor matrix
    let minor = Array.from({ length: v - 1 }, () =>
        Array(v - 1).fill(0)
    );

    for (let i = 0; i < v - 1; i++) {
        for (let j = 0; j < v - 1; j++) {
            minor[i][j] = L[i][j];
        }
    }

    // Determinant
    return Math.round(determinant(minor, v - 1));
}

